"use strict";(globalThis.webpackChunkp2d_control_tower_docs=globalThis.webpackChunkp2d_control_tower_docs||[]).push([[149],{1243(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"adminSidebar":[{"type":"link","href":"/msa-station-docs/","label":"MSA Station TMS User Guide","docId":"intro","unlisted":false},{"type":"category","label":"\ud83d\ude80 Getting Started","items":[{"type":"link","href":"/msa-station-docs/getting-started/dashboard","label":"Dashboard","docId":"getting-started/dashboard","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\uddc2\ufe0f Master Data","items":[{"type":"link","href":"/msa-station-docs/master-data/shipper","label":"Shipper","docId":"master-data/shipper","unlisted":false},{"type":"link","href":"/msa-station-docs/master-data/consignee","label":"Consignee","docId":"master-data/consignee","unlisted":false},{"type":"link","href":"/msa-station-docs/master-data/contract","label":"Contract","docId":"master-data/contract","unlisted":false},{"type":"link","href":"/msa-station-docs/master-data/price","label":"Price","docId":"master-data/price","unlisted":false},{"type":"link","href":"/msa-station-docs/master-data/price-check","label":"Price Check","docId":"master-data/price-check","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\udce6 AWB Data","items":[{"type":"link","href":"/msa-station-docs/awb-data/upload-data","label":"Upload Data","docId":"awb-data/upload-data","unlisted":false},{"type":"link","href":"/msa-station-docs/awb-data/entry-data","label":"Entry Data (Booking Order)","docId":"awb-data/entry-data","unlisted":false},{"type":"link","href":"/msa-station-docs/awb-data/delivery-order","label":"Delivery Order (Manifest)","docId":"awb-data/delivery-order","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\ude9a Driver","items":[{"type":"link","href":"/msa-station-docs/driver/order-driver","label":"Order Driver","docId":"driver/order-driver","unlisted":false},{"type":"link","href":"/msa-station-docs/driver/booking-driver","label":"Booking Driver","docId":"driver/booking-driver","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\udccd Tracking","items":[{"type":"link","href":"/msa-station-docs/tracking/live-tracking","label":"Live Tracking","docId":"tracking/live-tracking","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\ud83d\udcca Report Data","items":[{"type":"link","href":"/msa-station-docs/report-data/print-report-by-date","label":"Print Report By Date","docId":"report-data/print-report-by-date","unlisted":false},{"type":"link","href":"/msa-station-docs/report-data/print-sp","label":"Print SP","docId":"report-data/print-sp","unlisted":false},{"type":"link","href":"/msa-station-docs/report-data/invoices","label":"Invoices","docId":"report-data/invoices","unlisted":false},{"type":"link","href":"/msa-station-docs/report-data/update-status","label":"Update Status","docId":"report-data/update-status","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"awb-data/delivery-order":{"id":"awb-data/delivery-order","title":"Delivery Order (Manifest)","description":"The Delivery Order screen manages the manifest-level records used to generate delivery documents. It builds on the booking data and adds the customs/notification details (CN, Pemberitahu) needed to dispatch and document a shipment.","sidebar":"adminSidebar"},"awb-data/entry-data":{"id":"awb-data/entry-data","title":"Entry Data (Booking Order)","description":"The Entry Data screen is where you create and manage Shipping Instructions / Job Orders (JO) for domestic bookings. This is the core operational record that ties together the shipper, consignee, route, cargo details, and pricing.","sidebar":"adminSidebar"},"awb-data/upload-data":{"id":"awb-data/upload-data","title":"Upload Data","description":"The Upload Data module lets you bulk-import shipment/manifest files by dragging and dropping them into the system. Files are organized by manifest category so the system knows how to process each upload.","sidebar":"adminSidebar"},"driver/booking-driver":{"id":"driver/booking-driver","title":"Booking Driver","description":"The Booking Driver module tracks the driver-side status of each dispatched order. It\'s where the driver\'s progress \u2014 and the proof of pickup/delivery \u2014 is recorded against a booking.","sidebar":"adminSidebar"},"driver/order-driver":{"id":"driver/order-driver","title":"Order Driver","description":"The Order Driver module is where you create pickup/delivery orders and assign them to a vehicle and driver. It turns a booking into an actionable dispatch task.","sidebar":"adminSidebar"},"getting-started/dashboard":{"id":"getting-started/dashboard","title":"Dashboard","description":"After a successful login, you land on the Dashboard \u2014 the central control panel of MSA Station TMS. It gives you an at-a-glance overview of daily activity and quick access to every module.","sidebar":"adminSidebar"},"intro":{"id":"intro","title":"MSA Station TMS User Guide","description":"MSA Station TMS is the Transport Management System operated by MSA Kargo. It provides a centralized platform for managing delivery orders, driver dispatch, shipment tracking, and last-mile logistics operations.","sidebar":"adminSidebar"},"master-data/consignee":{"id":"master-data/consignee","title":"Consignee","description":"The Consignee module stores the master records of every recipient (the party receiving the goods). Saving consignees here lets you select them instantly during booking and delivery order creation.","sidebar":"adminSidebar"},"master-data/contract":{"id":"master-data/contract","title":"Contract","description":"The Contract module records the service agreements that govern your pricing. A contract defines a named agreement with a validity period; pricing entries (see Price) are then attached to it.","sidebar":"adminSidebar"},"master-data/price":{"id":"master-data/price","title":"Price","description":"The Price module defines the rates for each contract by route (origin \u2192 destination), product, and contract type. These rates are used automatically when calculating shipment costs and selling prices during booking.","sidebar":"adminSidebar"},"master-data/price-check":{"id":"master-data/price-check","title":"Price Check","description":"The Price Check tool lets you quickly look up the applicable rate for a given contract and route without scrolling through the full price list. It\'s handy when quoting a customer or verifying a charge.","sidebar":"adminSidebar"},"master-data/shipper":{"id":"master-data/shipper","title":"Shipper","description":"The Shipper module stores the master records of every sender (consignor) you work with. Once a shipper is saved here, you can quickly select it whenever you create a booking or shipping instruction instead of re-typing the details each time.","sidebar":"adminSidebar"},"report-data/invoices":{"id":"report-data/invoices","title":"Invoices","description":"The Invoices module lists all billing documents and lets you review, print, and track the payment status of each invoice.","sidebar":"adminSidebar"},"report-data/print-report-by-date":{"id":"report-data/print-report-by-date","title":"Print Report By Date","description":"The Print Report By Date tool generates a manifest report for all shipments departing on a chosen date, ready for printing.","sidebar":"adminSidebar"},"report-data/print-sp":{"id":"report-data/print-sp","title":"Print SP","description":"The Print SP tool lets you search for a specific Job Order and print its SP (Surat Perintah / work order document).","sidebar":"adminSidebar"},"report-data/update-status":{"id":"report-data/update-status","title":"Update Status","description":"The Update Status screens let each operational role advance a shipment\'s status as it moves through the pipeline. There is a dedicated screen per role so that responsibilities stay clear, plus an All view for supervisors.","sidebar":"adminSidebar"},"tracking/live-tracking":{"id":"tracking/live-tracking","title":"Live Tracking","description":"The Live Tracking module shows the real-time location of your shipments and drivers on an interactive map.","sidebar":"adminSidebar"}}}}')}}]);